61:   function loadState() {
62:     try {
63:       const saved = JSON.parse(localStorage.getItem(SAVE_KEY));
64:       if (!saved) return defaultState();
65:       const defaults = defaultState();
66:       const fresh = { ...defaults, ...saved, upgrades: { ...defaults.upgrades, ...(saved.upgrades || {}) }, pathLevels: { ...defaults.pathLevels, ...(saved.pathLevels || {}) }, herbs: { ...defaults.herbs, ...(saved.herbs || {}) }, equipment: { ...defaults.equipment, ...(saved.equipment || {}) }, milestones: saved.milestones || [] };
67:       Object.keys(fresh.equipment).forEach(id => { fresh.equipment[id] = { owned: false, level: 0, ...(fresh.equipment[id] || {}) }; });
68:       if (!sects[fresh.sectId]) fresh.sectId = 'azure';
69:       fresh.maxHp = Math.max(60, Number(fresh.maxHp) || 60);
70:       fresh.hp = Math.max(0, Math.min(fresh.maxHp, Number(fresh.hp ?? fresh.maxHp)));
