73:         fresh.totalSeconds += away;
74:         fresh.qiToday += fresh.active ? away * rateFor(fresh) : 0;
75:         fresh.medSeconds += fresh.active ? away : 0;
76:         fresh.qi += away * (fresh.active ? rateFor(fresh) : .15);
77:         fresh.totalQi += away * (fresh.active ? rateFor(fresh) : .15);
78:         fresh.stones += Math.floor(away / 8);
79:         const day = Math.floor(fresh.totalSeconds / 300) + 1;
80:         if (day !== fresh.dailyDate) { fresh.dailyDate = day; fresh.dailyClaimed = false; fresh.qiToday = 0; fresh.medSeconds = 0; fresh.tripToday = 0; }
81:         fresh.active = false;
