96:   function attackDamage(base) { return Math.round((base + gearStat('attack')) * (1 + sectData().attack + state.sectRank * .03)); }
97:   function rateFor(s = state) { return (0.8 + s.upgrades.sutra * .45 + (s.pathLevels?.spirit || 0) * .2) * (1 + s.boosts + gearStat('qi', s) + sectData(s).qi + s.sectRank * .02) * (s.active ? 1 : .2); }
98:   function currentSpell() { return sectSpells[state.sectId] || sectSpells.azure; }
99:   function damageEnemy(damage, source) {
100:     const enemy = state.enemy;
101:     if (!enemy) return;
102:     enemy.hp -= damage;
103:     if (enemy.hp <= 0) {
104:       state.enemy = null; state.wins = (state.wins || 0) + 1;
105:       state.stones += enemy.stones; addRep(enemy.rep);
106:       if (enemy.drop && state.herbs[enemy.drop] !== undefined) state.herbs[enemy.drop] += 1;
107:       if (state.mission) state.mission.progress = Math.min(state.mission.progress + 1, missions.find(m => m.id === state.mission.id)?.target || Infinity);
108:       showToast(`${enemy.name} defeated · +${enemy.stones} stones · +${enemy.rep} merit${enemy.drop ? ` · ${enemy.drop} gathered` : ''}`);
109:       return;
110:     }
111:     const taken = Math.max(1, enemy.damage - Math.floor(state.pathLevels.body / 2) - Math.floor(gearStat('guard')));
112:     state.hp = Math.max(0, state.hp - taken);
113:     if (state.hp <= 0) {
114:       state.enemy = null; state.hp = Math.max(1, Math.floor(state.maxHp * .35));
115:       showToast(`You were overcome and carried to safety · restored to ${state.hp} health.`);
116:     } else showToast(`${source} dealt ${damage} damage and suffered ${taken} in return.`);
117:   }
118:   function currentBand(stage = state.stage) { return realmBands.find(b => stage >= b.start && stage <= b.end); }
119:   function realmTitle(stage = state.stage) {
120:     if (stage === 0) return 'Mortal';
121:     const band = currentBand(stage);
122:     const level = stage < 10 ? stage : ((stage - band.start) % 3) + 1;
123:     return `${band.name} ${level}`;
124:   }
125:   function showToast(message) {
126:     const toast = $('toast'); toast.textContent = message; toast.classList.add('show');
127:     clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('show'), 2600);
128:   }
129:   function addStones(amount, reason) { state.stones += amount; if (reason) showToast(`${reason} · +${amount} spirit stones`); }
130:   const sectRanks = [
131:     { name: 'Outer Disciple', need: 0 }, { name: 'Inner Disciple', need: 20 },
132:     { name: 'Core Disciple', need: 60 }, { name: 'Elder', need: 120 }, { name: 'Sect Master', need: 220 }
133:   ];
134:   function addRep(amount) {
135:     state.sectRep += amount;
136:     while (state.sectRank < sectRanks.length - 1 && state.sectRep >= sectRanks[state.sectRank + 1].need) {
137:       state.sectRank += 1;
138:       state.hp += 10;
139:       showToast(`Sect promotion · ${sectRanks[state.sectRank].name}! Maximum health +10.`);
140:     }
141:   }
142:   function render() {
143:     const goal = requirement();
144:     const qi = Math.floor(state.qi);
145:     $('stones').textContent = nfmt(state.stones);
146:     $('realmName').textContent = realmTitle();
147:     $('stageBadge').innerHTML = `${state.stage === 0 ? '凡人' : currentBand().cn} <span>${String(state.stage === 0 ? 1 : ((state.stage - 1) % 3) + 1).padStart(2, '0')}</span>`;
148:     $('qiText').textContent = nfmt(qi); $('qiGoal').textContent = nfmt(goal);
149:     $('qiFill').style.width = `${Math.min(100, qi / goal * 100)}%`;
150:     $('qiPercent').textContent = `${Math.min(100, Math.floor(qi / goal * 100))}%`;
151:     $('qiRate').textContent = rateFor().toFixed(1);
152:     $('meditateLabel').textContent = state.active ? 'Meditation in progress' : 'Begin Meditation';
153:     $('meditateHint').textContent = state.active ? 'BREATHE DEEPLY · THE QI GATHERS' : 'LET THE QI FLOW THROUGH YOU';
154:     $('meditateBtn').classList.toggle('meditating', state.active);
155:     const canBreak = state.qi >= goal;
156:     $('breakthroughBtn').disabled = !canBreak;
157:     $('breakHint').textContent = canBreak ? `READY · ${breakChance()}% SUCCESS` : `${nfmt(Math.max(0, goal - qi))} QI TO THE THRESHOLD`;
158:     const control = Math.max(1, 1 + state.stage + state.upgrades.sutra * 2);
159:     const spirit = Math.max(1, 1 + Math.floor(state.stage / 2) + state.upgrades.array * 2 + state.pathLevels.spirit * 3);
160:     const body = Math.max(1, 1 + state.stage + state.upgrades.body * 2 + state.pathLevels.body * 3);
161:     state.maxHp = Math.max(60, 60 + body * 5 + state.pathLevels.body * 12 + state.sectRank * 10 + gearStat('health'));
162:     state.hp = Math.min(state.hp, state.maxHp);
163:     $('sectRankLabel').textContent = sectRanks[state.sectRank]?.name || sectRanks[0].name;
164:     $('sectName').textContent = sectData().name;
165:     [['control', control], ['spirit', spirit], ['body', body]].forEach(([key, val]) => {
166:       $(`${key}Stat`).textContent = val; $(`${key}Meter`).style.width = `${Math.min(100, 8 + val * 8)}%`;
167:     });
168:     $('dayCount').textContent = String(Math.floor(state.totalSeconds / 300) + 1).padStart(2, '0');
169:     $('welcomeDay').textContent = Math.floor(state.totalSeconds / 300) + 1;
170:     const meditateDone = state.medSeconds >= 30;
171:     const qiDone = state.qiToday >= 100;
172:     const tripDone = (state.tripToday || 0) > 0;
173:     [['taskMeditate', meditateDone], ['taskQi', qiDone], ['taskTrip', tripDone]].forEach(([id, done]) => $(id).classList.toggle('done', done));
174:     const taskCount = [meditateDone, qiDone, tripDone].filter(Boolean).length;
175:     $('taskProgress').textContent = `${state.dailyClaimed ? 3 : taskCount} / 3`;
176:     $('dailyClaim').disabled = state.dailyClaimed || taskCount < 3;
177:     $('dailyClaim').textContent = state.dailyClaimed ? 'Daily reward claimed' : taskCount === 3 ? 'Claim daily reward →' : 'Complete all practices →';
178:     const nextTitle = state.stage === 0 ? 'First breath' : `Step ${state.stage + 1} · ${realmTitle(state.stage + 1)}`;
179:     $('nextTitle').textContent = nextTitle;
180:     $('nextText').textContent = state.stage === 0 ? 'Gather 100 qi and take your first step into the cultivation world.' : `Refine ${nfmt(goal)} qi to advance toward ${realmTitle(state.stage + 1)}.`;
181:     $('nextProgress').textContent = `${nfmt(qi)} / ${nfmt(goal)} qi`;
182:     $('nextFill').style.width = `${Math.min(100, state.qi / goal * 100)}%`;
183:     $('techCount').textContent = `${Object.values(state.upgrades).reduce((a,b)=>a+b,0)}/∞`;
184:     $('expDot').classList.toggle('hidden', !(state.trip && Date.now() >= state.trip.ends));
