187:   function renderPath() {
188:     const milestones = [0, 1, 10, 13, 16, 19, 22];
189:     const labels = ['Mortal', 'Qi Cond.', 'Foundation', 'Golden Core', 'Nascent Soul', 'Spirit Severing', 'Dao Ascendant'];
190:     $('realmPath').innerHTML = milestones.map((stage, i) => `<div class="realm-step ${state.stage >= stage ? 'passed' : ''} ${state.stage >= stage && (i === milestones.length - 1 || state.stage < milestones[i+1]) ? 'current' : ''}"><span class="realm-node">${state.stage >= stage ? '✦' : '·'}</span><span>${labels[i]}</span></div>`).join('');
191:   }
192:   function breakChance() { return Math.min(99, 78 + state.upgrades.body * 4 + Math.min(state.stage, 5)); }
193:   function subHead(eyebrow, title, copy, symbol = '✧') {
194:     return `<div class="subview-head"><div><div class="eyebrow"><span class="eyebrow-line"></span>${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div><div class="day-chip"><span class="sun-mark">${symbol}</span><span><small>YOUR CURRENT REALM</small><b>${realmTitle()}</b></span></div></div>`;
