199:       return `<article class="technique-card"><div class="tech-seal">${t.seal}</div><div class="tech-copy"><h3>${t.name}</h3><p>${t.desc}</p><div class="tech-level">RANK ${level} · ${t.effect}</div></div><button class="buy-btn" data-action="upgrade" data-id="${t.id}" ${state.stones < cost ? 'disabled' : ''}>Attune<span>◇ ${cost}</span></button></article>`;
200:     }).join('');
201:     $('view-techniques').innerHTML = `${subHead('THE SECT LIBRARY', 'Cultivation techniques', 'Master ancient arts to deepen your foundation.', '☯')}<div class="subview-layout"><div class="subview-main"><article class="content-panel"><div class="eyebrow">THREE SCROLLS AWAIT</div><h2>Choose what to cultivate</h2><p>Each technique may be attuned again and again. Higher ranks demand more spirit stones, but their effects endure.</p>${cards}</article></div><aside class="subview-aside"><article class="feature-card"><div class="eyebrow">CURRENTLY PRACTICING</div><h3>${state.active ? 'Clear your mind' : 'A quiet mind is a clear vessel'}</h3><p>${state.active ? `Your breath gathers ${rateFor().toFixed(1)} qi each second. Let the cycle continue.` : 'Begin meditation from the Cultivation Grove to gather vital essence even while you explore the sect.'}</p><div class="feature-stats"><span>QI FLOW <b>${rateFor().toFixed(1)} / sec</b></span><span>BREAKTHROUGH <b>${breakChance()}%</b></span></div></article><article class="content-panel"><div class="eyebrow">LEARNER'S NOTE</div><h2>Attunement</h2><p>Spend spirit stones to bind a scroll to your meridians. Effects are permanent and stack with each rank.</p><div class="inventory-row"><span>Spirit stones</span><b>◇ ${nfmt(state.stones)}</b></div></article></aside></div>`;
202:   }
203:   function renderExpeditions() {
204:     const list = [
205:       { id: 'herbs', name: 'Gathering in the Mistwood', icon: '林', desc: 'Follow the dew trails through the foothills. Return with medicinal herbs and a modest stone offering.', duration: 25, reward: 18, loot: '3 herbs · 1 ironroot' },
206:       { id: 'ruins', name: 'The Moonlit Ruins', icon: '月', desc: 'Search a forgotten shrine for spirit stones, ironroot, and rare moonflowers.', duration: 60, reward: 48, loot: '2 ironroot · 2 moonflowers' }
207:     ];
208:     let tripState = '';
209:     if (state.trip) {
210:       const left = Math.max(0, Math.ceil((state.trip.ends - Date.now()) / 1000));
211:       tripState = left ? `<div class="timer">Returning in ${Math.floor(left / 60)}:${String(left % 60).padStart(2, '0')}</div>` : `<div class="timer ready">Journey complete · ready to collect</div>`;
212:     }
213:     const cards = list.map(t => `<article class="expedition-card"><div class="expedition-art">${t.icon}</div><div><h3>${t.name}</h3><p>${t.desc}</p><div class="exp-meta"><span>◷ ${t.duration}s</span><span>◇ ${t.reward + state.stage * 2} stones</span><span>✿ ${t.loot}</span></div>${state.trip && state.trip.id === t.id ? tripState : ''}</div>${state.trip ? (state.trip.id === t.id && Date.now() >= state.trip.ends ? `<button class="action-btn" data-action="collect-trip">Collect</button>` : `<button class="action-btn" disabled>${state.trip.id === t.id ? 'In progress' : 'Away'}</button>`) : `<button class="action-btn" data-action="start-trip" data-id="${t.id}" data-duration="${t.duration}" data-reward="${t.reward}">Set out</button>`}</article>`).join('');
214:     $('view-expeditions').innerHTML = `${subHead('BEYOND THE SECT WALLS', 'Expeditions', 'The world is vast. A cultivator must also walk its roads.', '⌁')}<div class="subview-layout"><div class="subview-main"><article class="content-panel"><div class="eyebrow">AVAILABLE JOURNEYS</div><h2>Choose a path</h2><p>Send your spirit out into the world. You can continue cultivating while an expedition is underway.</p>${cards}</article></div><aside class="subview-aside"><article class="feature-card"><div class="eyebrow">TRAVELER'S LEDGER</div><h3>${state.completedTrips} journeys completed</h3><p>Every safe return brings new spirit stones to the Azure Cloud Sect. Higher realms draw richer offerings.</p><div class="feature-stats"><span>STONE YIELD <b>+${state.stage * 2} / trip</b></span></div></article><article class="content-panel"><div class="eyebrow">FIELD TIP</div><h2>Time moves on</h2><p>Expeditions progress while you visit other pages. Leave the game open, or return later to collect your findings.</p></article></aside></div>`;
215:   }
